-- 561: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 8 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_561_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_561_guard;
INSERT INTO _migration_561_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_029' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_mig' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a push factor of rural-urban migration in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Lack of jobs and social amenities in the villages","B. Better-paid employment in the cities","C. Abundant fertile farmland in the village","D. Peaceful and secure rural communities"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Push factors are conditions at the origin that drive people away — rural poverty, few jobs and poor schools, hospitals and water supply. Better-paid city jobs are a pull factor (an attraction at the destination), and abundant farmland and peace would keep people in the village rather than push them out. Therefore the correct answer is A: Lack of jobs and social amenities in the villages.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_029' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_561_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_030' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_mig' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The persistent departure of highly trained Ghanaians such as doctors, nurses and lecturers to work abroad is commonly referred to as...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Labour turnover","B. Brain drain","C. Deportation","D. Internal migration"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Brain drain is the loss of skilled human capital through emigration, which deprives Ghana’s hospitals and universities of expertise the state paid to train. Labour turnover is routine movement between jobs, deportation is forced removal by a state, and internal migration stays within Ghana’s borders. Therefore the correct answer is B: Brain drain.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_030' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_561_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_031' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_mig' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The dependency ratio of a population measures...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The ratio of births to deaths in a year","B. The share of the population in formal employment","C. The proportion of the young and the elderly who depend on the working-age population","D. The number of dependants a taxpayer claims"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The dependency ratio compares those below 15 and above 64 with the working-age group (15–64); a high ratio means each worker supports many non-workers, straining family income and state services. (Births-to-deaths is about natural increase, and formal employment share and tax claims are unrelated concepts.) Therefore the correct answer is C: The proportion of the young and the elderly who depend on the working-age population.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_031' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_561_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_032' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_mig' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a negative effect of rapid urban growth driven by rural-urban migration in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A steady fall in the urban population","B. Reduced demand for urban services","C. The disappearance of traffic congestion","D. The growth of overcrowded slums and severe pressure on housing and sanitation"]' AND q.correct_answer IS 'D' AND q.explanation IS 'When migration outpaces planning, cities such as Accra and Kumasi develop overcrowded settlements where housing, water, toilets and waste disposal cannot cope. The other options are the opposite of what happens: rapid in-migration raises the urban population and the demand for services, and worsens congestion. Therefore the correct answer is D: The growth of overcrowded slums and severe pressure on housing and sanitation.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Select' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_032' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_029', 'topic_wassce_p2_soc_mig', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is a push factor of rural-urban migration in Ghana?', 'multiple_choice', NULL, '["A. Lack of jobs and social amenities in the villages","B. Better-paid employment in the cities","C. Abundant fertile farmland in the village","D. Peaceful and secure rural communities"]', 'A', 'Push factors are conditions at the origin that drive people away — rural poverty, few jobs and poor schools, hospitals and water supply. Better-paid city jobs are a pull factor (an attraction at the destination), and abundant farmland and peace would keep people in the village rather than push them out. Therefore the correct answer is A: Lack of jobs and social amenities in the villages.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec');
