INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_032', 'topic_wassce_p2_soc_mig', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is a negative effect of rapid urban growth driven by rural-urban migration in Ghana?', 'multiple_choice', NULL, '["A. A steady fall in the urban population","B. Reduced demand for urban services","C. The disappearance of traffic congestion","D. The growth of overcrowded slums and severe pressure on housing and sanitation"]', 'D', 'When migration outpaces planning, cities such as Accra and Kumasi develop overcrowded settlements where housing, water, toilets and waste disposal cannot cope. The other options are the opposite of what happens: rapid in-migration raises the urban population and the demand for services, and worsens congestion. Therefore the correct answer is D: The growth of overcrowded slums and severe pressure on housing and sanitation.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Select', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-social-studies-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_was_soc_s3_029', 'q_was_soc_s3_030', 'q_was_soc_s3_031', 'q_was_soc_s3_032');
